def answer(question: str) -> Answer:
    q_vec = embed(question)
    hits = hybrid_search(q_vec, question, k=40)
    top = rerank(question, hits)[:8]
    if top[0].score < 0.35:
        return Answer.not_found(suggest=top[:3])
    context = "\n\n".join(h.text for h in top)
    reply = llm.generate(PROMPT.format(q=question, ctx=context))
    return Answer(reply, sources=[h.url for h in top])
